 async function catalogTemplate(){lock(true);try{const X=await xlsx();if(!valid())return;const book=X.utils.book_new(),sheet=X.utils.aoa_to_sheet([['SKU','Nome','Tipo','Valor de custo','Valor de venda']]);sheet['!cols']=[{wch:20},{wch:45},{wch:12},{wch:20},{wch:20}];X.utils.book_append_sheet(book,sheet,'Produtos EG');check(await db.rpc('pdi_eg_export_log',{p_kind:'products',p_count:0,p_filters:{template:true}}));if(!valid())return;const bytes=X.write(book,{type:'array',bookType:'xls'}),url=URL.createObjectURL(new Blob([bytes],{type:'application/vnd.ms-excel'})),link=h('a');link.href=url;link.download='modelo-produtos-erika-glass.xls';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}finally{if(valid())lock(false);}}
 function catalogImport(){let staged=[];openDialog('Importar catálogo',form=>{note(form,'Use SKU, Nome, Tipo (item/kit), Preço venda e Custo. O arquivo fica no navegador; confirme a prévia antes de atualizar. SKUs existentes mantêm sua composição. Kits novos precisam ser configurados depois.');const template=button('Baixar modelo XLS',catalogTemplate);template.classList.add('eg-export');form.append(template);const file=field(form,'Planilha XLS ou XLSX · até 5 MB','file','file','',true);file.accept='.xls,.xlsx';const preview=h('div','eg-import-preview'),ack=field(form,'Conferi os produtos e autorizo cadastrar/atualizar estes SKUs','confirm','checkbox','',true);form.append(preview);file.addEventListener('change',async()=>{staged=[];ack.checked=false;preview.replaceChildren();const selected=file.files[0];if(!selected)return;if(selected.size>5*1024*1024){preview.textContent='Use um arquivo de até 5 MB.';return;}lock(true);try{const reader=await xlsx();if(!valid()||!dialog)return;const workbook=reader.read(await selected.arrayBuffer(),{type:'array',cellDates:false,cellFormula:true});staged=M().catalogWorkbook(workbook,data.products);preview.append(h('p','',`${staged.length} produto(s) na prévia. Nenhum registro foi salvo.`));table(preview,['SKU','Produto','Tipo','Venda','Custo'],staged.map(row=>[row.sku,row.name,labels[row.kind],brl(row.sale_cents),brl(row.cost_cents)]));dirty=true;}catch(e){preview.textContent=e.message;}finally{if(valid())lock(false);}});return ()=>{if(!staged.length||!ack.checked)throw Error('Carregue o arquivo e confira a prévia.');return {rows:staged,file:file.files[0].name};};},payload=>command('product_import',payload));}
 function reports(){const section=card('Relatórios diários de vendas');section.append(button('Registrar dia',()=>reportEditor(),true));note(section,'Cada visita informada precisa de uma empresa selecionada. Um relatório por colaborador e dia; a agenda da promotoria permanece separada.');recordsList(section,filtered().filter(row=>row.kind==='report'),row=>`${row.data.visits} visita(s) · ${row.data.quotes} orçamento(s) · ${brl(row.data.quoted_cents)}`,row=>reportEditor(row));}
 function reportEditor(existing=null){recordForm('report_save',existing?'Ajustar relatório diário':'Relatório diário',form=>{const date=workDate(form,existing),getSubject=subject(form,existing),visits=field(form,'Quantidade de visitas','visits','number',existing?.data.visits??'',true),quotes=field(form,'Quantidade de orçamentos','quotes','number',existing?.data.quotes??'',true),quoted=field(form,'Valor total orçado · R$','quoted','text',real(existing?.data.quoted_cents),true);visits.min=quotes.min=0;visits.max=100;quotes.max=1000000;visits.step=quotes.step=1;quoted.inputMode='decimal';const companyList=h('div','eg-company-list');form.append(companyList);let selects=[];function update(){const old=selects.map(node=>node.value);selects=[];companyList.replaceChildren();const count=/^\d+$/.test(visits.value)?Number(visits.value):0;if(count>100)return;for(let i=0;i<count;i++){const select=field(companyList,`Empresa da visita ${i+1}`,'company-'+i,'select','',true);selectOptions(select,data.companies.filter(row=>row.active).map(row=>[row.id,row.name]));select.value=old[i]||existing?.data.companies?.[i]||'';selects.push(select);}}visits.addEventListener('input',update);update();const memo=notes(form,existing?.data.notes);return ()=>({date:date.value,subject_id:getSubject(),visits:M().integer(visits.value,{max:100}),quotes:M().integer(quotes.value),quoted_cents:M().money(quoted.value),companies:selects.map(node=>node.value),notes:memo.value.trim()});},existing);}
 function ordersView(){const section=card('Pedidos fechados');if(context.can_sales)section.append(button('Fechar pedido',orderEditor,true));note(section,'Pedido fechado exige empresa com CPF/CNPJ válido. Parcelas são previsões; somente as baixas representam recebimentos registrados. A entrega baixa os produtos acabados.');recordsList(section,filtered().filter(row=>row.kind==='order'),row=>`${row.data.company_name} · ${brl(row.data.total_cents)} · ${row.data.items?.length||0} item(ns)`,null,row=>{const actions=h('div','eg-actions');actions.append(button('Ver pedido',()=>orderDetails(row)));if(context.can_manage&&row.status==='closed')actions.append(button('Confirmar entrega',()=>simpleDateAction('order_deliver','Confirmar entrega',row)));return actions;});}
 function orderEditor(){recordForm('order_save','Fechar pedido',form=>{const date=workDate(form),getSubject=subject(form),company=field(form,'Empresa / CPF ou CNPJ','company','select','',true);selectOptions(company,data.companies.filter(row=>row.active).map(row=>[row.id,`${row.name}${M().validDocument(row.document)?'':' · documento pendente'}`]));const documentSelect=field(form,'CPF/CNPJ da empresa','document','select','',true);selectOptions(documentSelect,data.companies.filter(row=>row.active&&M().validDocument(row.document)).map(row=>[row.id,`${row.document} · ${row.name}`]));company.addEventListener('change',()=>{documentSelect.value=company.value;});documentSelect.addEventListener('change',()=>{company.value=documentSelect.value;});const itemsBox=h('fieldset','eg-items');itemsBox.append(h('legend','','Itens do pedido'));form.append(itemsBox);const lines=[],totalOutput=h('output','eg-order-total','Total: R$ 0,00');function calculate(){try{const value=M().total(lines.map(line=>({quantity:line.quantity.value,unit_cents:M().money(line.price.value)})));totalOutput.textContent='Total: '+brl(value);return value;}catch(_){totalOutput.textContent='Preencha quantidade e preço dos itens.';return null;}}function add(){if(lines.length>=200)throw Error('Pedido limitado a duzentos itens.');const line=h('div','eg-line'),product=field(line,'Produto','product','select','',true),quantity=field(line,'Quantidade','quantity','number',1,true),price=field(line,'Preço unitário · R$','price','text','',true);selectOptions(product,products().map(row=>[row.id,`${row.sku} · ${row.name}`]));quantity.min=1;quantity.max=1000000;quantity.step=1;price.inputMode='decimal';const entry={product,quantity,price};lines.push(entry);product.addEventListener('change',()=>{price.value=real(data.products.find(row=>row.id===product.value)?.sale_cents);calculate();});quantity.addEventListener('input',calculate);price.addEventListener('input',calculate);line.append(button('Remover item',()=>{lines.splice(lines.indexOf(entry),1);line.remove();calculate();dirty=true;}));itemsBox.append(line);}itemsBox.append(button('Adicionar item',()=>{try{add();dirty=true;}catch(e){message(e.message,true);}}));add();form.append(totalOutput);const quoted=field(form,'Valor orçado deste pedido · R$ (vazio = total do pedido)','quoted','text');quoted.inputMode='decimal';const payment=field(form,'Condição de pagamento','payment','select');selectOptions(payment,[['cash','À vista'],['boleto','Boleto']],null);const count=field(form,'Quantidade de parcelas','count','number',1,true),first=field(form,'Primeiro vencimento','first','date',date.value,true);count.min=1;count.max=60;count.step=1;const installmentsBox=h('div','eg-installments');form.append(installmentsBox);let installmentFields=[];function generate(){const value=calculate();if(!value)throw Error('Inclua itens com total positivo antes de gerar parcelas.');const rows=M().installments(value,payment.value==='cash'?1:count.value,payment.value==='cash'?date.value:first.value);installmentsBox.replaceChildren();installmentFields=rows.map(row=>{const line=h('div','eg-line'),due=field(line,`Parcela ${row.number} · vencimento`,'due','date',row.date,true),amount=field(line,'Valor · R$','amount','text',real(row.amount_cents),true);amount.inputMode='decimal';installmentsBox.append(line);return {due,amount};});dirty=true;}form.append(button('Gerar / recalcular parcelas',()=>{try{generate();}catch(e){message(e.message,true);}}));payment.addEventListener('change',()=>{count.value=1;count.disabled=payment.value==='cash';first.value=date.value;installmentFields=[];installmentsBox.replaceChildren();});count.disabled=true;const memo=notes(form);return ()=>{const selected=data.companies.find(row=>row.id===company.value);if(!selected||!M().validDocument(selected.document))throw Error('A empresa precisa de CPF/CNPJ válido para fechar o pedido.');if(!lines.length)throw Error('Adicione pelo menos um item.');const items=lines.map(line=>({product_id:line.product.value,quantity:M().integer(line.quantity.value,{min:1}),unit_cents:M().money(line.price.value)}));const total=M().total(items);if(!total)throw Error('O total deve ser positivo.');if(!installmentFields.length)generate();const installments=installmentFields.map(line=>({date:M().date(line.due.value),amount_cents:M().money(line.amount.value)}));if(M().sum(installments.map(row=>row.amount_cents))!==total)throw Error('A soma das parcelas deve ser igual ao total do pedido.');return {date:date.value,subject_id:getSubject(),company_id:company.value,items,payment:payment.value,installments,quoted_cents:quoted.value.trim()?M().money(quoted.value):total,notes:memo.value.trim()};};});}
 function orderDetails(row){openDialog('Detalhes do pedido',form=>{form.append(h('p','',`${row.data.company_name} · ${day(row.work_date)} · ${person(row.subject_id)}`));table(form,['SKU','Produto','Quantidade','Unitário','Total'],(row.data.items||[]).map(item=>[item.sku,item.name,item.quantity,brl(item.unit_cents),brl(item.total_cents)]));table(form,['Parcela','Vencimento','Valor'],(row.data.installments||[]).map(item=>[item.number,day(item.date),brl(item.amount_cents)]));note(form,row.data.notes||'Sem observações.');return ()=>null;});}
