 function visitsView(){const section=card('Agenda e atividades da promotoria');section.append(button('Agendar / registrar visita',()=>visitEditor(),true));note(section,'Registre local, atividades, ocorrências e até três fotos antes e três depois. Documento da empresa não é obrigatório para a visita.');recordsList(section,filtered().filter(row=>row.kind==='visit'),row=>`${companyName(row.company_id)} · ${row.data.activities}`,row=>visitEditor(row),row=>button('Fotos antes / depois',()=>photoDialog(row)));}
 function photoFile(file){if(!file||file.size<=0||file.size>5*1024*1024||!['image/jpeg','image/png','image/webp'].includes(file.type))throw Error('Escolha JPG, PNG ou WebP de até 5 MB.');return file;}
 async function attachPhoto(visit,entry){if(!valid())throw Error('A sessão ou a página mudou.');const file=photoFile(entry.file);entry.path=entry.path||`${context.user_id}/${visit.id}/${entry.phase}/${crypto.randomUUID()}.${{'image/jpeg':'jpg','image/png':'png','image/webp':'webp'}[file.type]}`;
 if(!entry.uploaded){const uploaded=await db.storage.from('pdi-eg-visits').upload(entry.path,file,{contentType:file.type,upsert:false});if(uploaded.error&&String(uploaded.error.statusCode||uploaded.error.status)!=='409')check(uploaded);entry.uploaded=true;}
 if(!valid())throw Error('A sessão mudou durante o envio.');check(await db.rpc('pdi_eg_photo',{p_action:'attach',p_visit:visit.id,p_phase:entry.phase,p_path:entry.path,p_name:file.name}));entry.attached=true;}
 function photoChoices(parent,onSelect){const controls=h('div','eg-actions');for(const[camera,label]of [[true,'Tirar foto'],[false,'Anexar da galeria']]){const input=h('input');input.type='file';input.accept='image/jpeg,image/png,image/webp';input.hidden=true;input.name=camera?'camera-photo':'gallery-photo';if(camera)input.setAttribute('capture','environment');else input.multiple=true;input.addEventListener('change',()=>{try{const files=Array.from(input.files||[]);files.forEach(photoFile);const result=onSelect(files);if(result&&typeof result.catch==='function')result.catch(error=>message(error.message,true));}catch(error){message(error.message,true);}finally{input.value='';}});controls.append(button(label,()=>input.click()),input);}parent.append(controls);return controls;}
 function visitPhotoPicker(form,visit){const entries=[];for(const phase of ['before','after']){const section=h('section','eg-photo-phase'),count=h('p','eg-note'),grid=h('div','eg-photo-grid');section.append(h('h3','',phase==='before'?'Fotos antes':'Fotos depois'));const existingCount=data.photos.filter(photo=>photo.visit_id===visit?.id&&photo.phase===phase&&photo.active!==false).length;const draw=()=>{count.textContent=`${existingCount+entries.filter(entry=>entry.phase===phase).length}/3 fotos selecionadas ou já salvas`;};photoChoices(section,files=>{if(existingCount+entries.filter(entry=>entry.phase===phase).length+files.length>3)throw Error('Máximo de três fotos antes e três depois.');for(const file of files){const entry={file,phase,attached:false,uploaded:false},figure=h('figure','eg-photo'),image=h('img'),url=URL.createObjectURL(file);image.src=url;image.alt=`Prévia: ${file.name}`;figure.append(photoPreview(image),h('figcaption','',file.name),button('Remover',()=>{if(entry.attached)throw Error('Esta foto já foi salva. Use Fotos antes / depois para removê-la.');closePhotoViewer();entries.splice(entries.indexOf(entry),1);figure.remove();URL.revokeObjectURL(url);draw();dirty=true;}));dialogCleanup.push(()=>URL.revokeObjectURL(url));entries.push(entry);grid.append(figure);}draw();dirty=true;});section.append(count,grid);draw();note(section,'Até três fotos de até 5 MB. As fotos selecionadas serão enviadas ao salvar a visita.');form.append(section);}return entries;}
 function visitEditor(existing=null){let savedVisit=null,savedPayload=null,getReason=null,entries=[];openDialog(existing?'Ajustar visita':'Registrar visita',form=>{const date=workDate(form,existing,true),getSubject=subject(form,existing),company=field(form,'Loja / empresa visitada','company','select','',true);selectOptions(company,data.companies.filter(row=>row.active).map(row=>[row.id,row.name]));company.value=existing?.company_id||'';const status=field(form,'Situação','status','select');selectOptions(status,[['planned','Agendada'],['done','Realizada']],null);status.value=existing?.status||'planned';const location=field(form,'Local da visita','location','text',existing?.data.location||''),activities=field(form,'Atividades da visita','activities','textarea',existing?.data.activities||'',true),occurrence=field(form,'Ocorrências da visita','occurrence','textarea',existing?.data.occurrence||''),memo=notes(form,existing?.data.notes);location.maxLength=500;activities.minLength=3;activities.maxLength=2000;occurrence.maxLength=1500;getReason=reason(form,existing);entries=visitPhotoPicker(form,existing);return ()=>{if(savedVisit)return savedPayload;if(status.value==='done'&&date.value>context.today)throw Error('Uma visita futura precisa permanecer agendada.');return {date:date.value,subject_id:getSubject(),company_id:company.value,status:status.value,location:location.value.trim(),activities:activities.value.trim(),occurrence:occurrence.value.trim(),notes:memo.value.trim()};};},async payload=>{if(!savedVisit){savedVisit=await command('visit_save',payload,existing,getReason?.());savedPayload=payload;for(const input of dialog.querySelectorAll('input,select,textarea'))if(!input.closest('.eg-photo-phase')){input.disabled=true;input.dataset.egDisabled='true';}}try{for(const entry of entries)if(!entry.attached)await attachPhoto(savedVisit,entry);}catch(error){throw Error('A visita foi salva, mas há foto pendente. Clique em Salvar para tentar o envio novamente. '+error.message);}});}
 function photoDialog(visit){openDialog('Fotos da visita',form=>{for(const phase of ['before','after']){const section=h('section','eg-photo-phase');section.append(h('h3','',phase==='before'?'Antes':'Depois'));const photos=data.photos.filter(photo=>photo.visit_id===visit.id&&photo.phase===phase&&photo.active!==false),grid=h('div','eg-photo-grid');section.append(grid);for(const photo of photos){const figure=h('figure','eg-photo'),image=h('img');image.alt=`${phase==='before'?'Antes':'Depois'} · ${photo.file_name}`;image.loading='lazy';image.referrerPolicy='no-referrer';const opener=photoPreview(image);figure.append(opener,h('figcaption','',photo.file_name));grid.append(figure);db.storage.from('pdi-eg-visits').createSignedUrl(photo.path,300).then(result=>{if(valid()&&figure.isConnected){try{image.src=check(result).signedUrl;image.dataset.egExpiresAt=String(Date.now()+300000);opener.disabled=false;}catch(e){figure.append(h('p','eg-error',e.message));}}});const mayEdit=context.can_manage||visit.subject_id===context.user_id; if(mayEdit)figure.append(button('Remover foto',async()=>{lock(true);try{check(await db.rpc('pdi_eg_photo',{p_action:'remove',p_visit:visit.id,p_phase:phase,p_path:photo.path,p_name:photo.file_name}));const removed=await db.storage.from('pdi-eg-visits').remove([photo.path]);if(removed.error)notify('Foto retirada da visita e preservada no armazenamento privado.',true);closeDialog();await load();if(valid())photoDialog(visit);}catch(e){message(e.message,true);}finally{if(valid())lock(false);}}));}const mayUpload=context.can_manage||visit.subject_id===context.user_id;if(mayUpload&&photos.length<3){photoChoices(section,asyncFiles=>{if(photos.length+asyncFiles.length>3)throw Error('Máximo de três fotos por etapa.');return(async()=>{lock(true);try{for(const file of asyncFiles)await attachPhoto(visit,{file,phase});closeDialog();await load();if(valid())photoDialog(visit);}catch(error){message(error.message,true);}finally{if(valid())lock(false);}})();});}else if(photos.length>=3)note(section,'Limite de três fotos desta etapa atingido.');form.append(section);}note(form,'As fotos são privadas. A prévia usa um endereço temporário e expira em cinco minutos.');return ()=>null;});}
 function stockView(){const section=card('Posição atual do estoque por estágio');const visibleProducts=data.products.filter(row=>!productFilter||row.id===productFilter);if(context.can_stock)section.append(button('Registrar entrada no almoxarifado',()=>movementEditor('stock_entry'),true));const balances=M().stock(data.moves),lookup=new Map(balances.map(row=>[row.product_id,row]));note(section,'Almoxarifado → transferência em trânsito → bruto E.G. → preparo → acabado. A saída do almoxarifado só entra no bruto após conferência do recebimento.');table(section,['SKU','Produto','Almoxarifado','Bruto E.G.','Acabado'],visibleProducts.map(product=>{const value=lookup.get(product.id)||{};return [product.sku,product.name,fmt(value.warehouse||0),fmt(value.raw||0),fmt(value.ready||0)];}));const availability=M().kits(data.products,balances).filter(kit=>!productFilter||kit.product_id===productFilter);if(availability.length){const kitCard=h('section','eg-kit-availability');kitCard.append(h('h3','','Kits possíveis com o bruto disponível'));table(kitCard,['Kit','Possíveis agora','Faltantes para uma unidade'],availability.map(kit=>[kit.name,kit.possible==null?'Composição pendente':fmt(kit.possible),kit.missing.length?kit.missing.map(part=>`${part.name}: faltam ${part.shortfall}`).join(' · '):kit.reason||'Sem faltantes para uma unidade']));section.append(kitCard);}section.append(button('Exportar posição CSV',()=>exportData('stock',['SKU','Produto','Almoxarifado','Bruto E.G.','Acabado'],visibleProducts.map(product=>{const value=lookup.get(product.id)||{};return [product.sku,product.name,value.warehouse||0,value.raw||0,value.ready||0];}))));const history=card('Entradas no período');recordsList(history,filtered().filter(row=>row.kind==='stock_entry'),row=>(row.data.items||[]).map(item=>`${item.quantity} × ${item.name}`).join(' · '));}
 function movementEditor(action){recordForm(action,action==='stock_entry'?'Entrada de estoque':'Enviar transferência ao E.G.',form=>{const date=workDate(form),box=h('div','eg-items'),lines=[];form.append(box);function add(){if(lines.length>=200)throw Error('Inclua no máximo duzentos itens.');const line=h('div','eg-line'),product=field(line,'Produto','product','select','',true),quantity=field(line,'Quantidade','quantity','number',1,true);selectOptions(product,products().map(row=>[row.id,`${row.sku} · ${row.name}`]));quantity.min=1;quantity.max=1000000;quantity.step=1;const entry={product,quantity};lines.push(entry);line.append(button('Remover item',()=>{lines.splice(lines.indexOf(entry),1);line.remove();dirty=true;}));box.append(line);}box.append(button('Adicionar item',()=>{try{add();dirty=true;}catch(e){message(e.message,true);}}));add();const memo=notes(form);return ()=>{if(!lines.length)throw Error('Adicione ao menos um item.');return {date:date.value,items:lines.map(line=>({product_id:line.product.value,quantity:M().integer(line.quantity.value,{min:1})})),notes:memo.value.trim()};};});}
 function transfersView(){const section=card('Transferências para Erika Glass');if(context.can_stock)section.append(button('Enviar transferência',()=>movementEditor('transfer_send'),true));recordsList(section,filtered().filter(row=>row.kind==='transfer'),row=>(row.data.items||[]).map(item=>`${item.quantity} × ${item.name}`).join(' · '),null,row=>{const actions=h('div','eg-actions');if(context.can_production&&row.status==='dispatched')actions.append(button('Conferir recebimento',()=>simpleDateAction('transfer_receive','Conferir recebimento',row,true)));if(context.can_production||context.can_stock)actions.append(button('Registrar ocorrência',()=>recordFormForParent('occurrence_add','Ocorrência da transferência',row,'description','Descreva a ocorrência')));return actions;});}
 function productionView(){charts();const section=card('Preparo e produtos acabados');const selected=filtered(),balances=M().stock(data.moves);metrics(section,[['Preparos registrados',fmt(selected.filter(row=>row.kind==='preparation').length),'No período'],['Unidades preparadas',fmt(M().sum(selected.filter(row=>row.kind==='preparation').map(row=>Number(row.data.quantity)))),'Itens e kits acabados informados'],['Transferências em trânsito',fmt(data.records.filter(row=>row.active&&row.kind==='transfer'&&row.status==='dispatched').length),'Aguardando conferência'],['Produtos com saldo acabado',fmt(balances.filter(row=>row.ready>0).length),'SKUs com saldo atual positivo']]);section.append(button('Registrar preparo',()=>recordForm('prepare','Registrar preparo',form=>{const date=workDate(form),getSubject=subject(form),product=field(form,'Produto / kit acabado','product','select','',true),quantity=field(form,'Quantidade concluída','quantity','number','',true);selectOptions(product,products().map(row=>[row.id,`${row.sku} · ${row.name} (${labels[row.kind]})`]));quantity.min=1;quantity.max=1000000;quantity.step=1;const memo=notes(form);note(form,'O preparo consome itens do bruto: kits usam sua composição cadastrada. Produtos prontos passam ao estágio Acabado.');return ()=>({date:date.value,subject_id:getSubject(),product_id:product.value,quantity:M().integer(quantity.value,{min:1}),notes:memo.value.trim()});}),true));recordsList(section,filtered().filter(row=>row.kind==='preparation'),row=>`${row.data.quantity} × ${row.data.product_name}`);const transferSection=card('Transferências aguardando conferência');recordsList(transferSection,data.records.filter(row=>row.active&&row.kind==='transfer'&&row.status==='dispatched'),row=>(row.data.items||[]).map(item=>`${item.quantity} × ${item.name}`).join(' · '),null,row=>button('Conferir recebimento',()=>simpleDateAction('transfer_receive','Conferir recebimento',row,true)));stockView();}
 function recordFormForParent(action,title,row,key,label){openDialog(title,form=>{const description=field(form,label,key,'textarea','',true);description.minLength=5;description.maxLength=2000;return ()=>({[key]:description.value.trim()});},payload=>command(action,payload,row));}
 function occurrencesView(){const section=card('Ocorrências de transferências');note(section,'Acompanhe a conferência, o encaminhamento e a resolução. As observações das visitas permanecem na própria visita.');recordsList(section,filtered().filter(row=>row.kind==='occurrence'),row=>`${row.data.description}${row.data.resolution?' · Solução: '+row.data.resolution:''}`,null,row=>row.status==='open'?button('Registrar solução',()=>recordFormForParent('occurrence_resolve','Resolver ocorrência',row,'resolution','Solução / encaminhamento')):h('span','eg-badge','Resolvida'));}
 function financeView(){
  charts();const section=card('Financeiro no período'),state=M().finance(data.records.filter(matchesRow),context.today),periodRows=filtered(),summary=M().summary(periodRows);
  const rows=state.schedule.filter(row=>(!start||row.date>=start)&&(!end||row.date<=end));
  metrics(section,[['Previsto no período',brl(M().sum(rows.map(row=>Number(row.amount_cents)))),'Parcelas por vencimento'],['Recebido no período',brl(M().sum(periodRows.filter(row=>row.kind==='receipt').map(row=>Number(row.data.amount_cents)))),'Baixas por data efetiva'],['Valor orçado no período',brl(summary.quoted_cents),'Relatórios diários'],['Orçamentos no período',fmt(summary.quotes),'Quantidade nos relatórios diários'],['Valor vendido no período',brl(summary.sold_cents),'Pedidos por data do fechamento'],['Ticket médio',brl(summary.ticket_cents),'Valor vendido / pedidos'],['A receber no período',brl(M().sum(rows.map(row=>row.remaining_cents))),'Saldo das parcelas com vencimento no recorte'],['Vencido no período',brl(M().sum(rows.filter(row=>row.overdue).map(row=>row.remaining_cents))),'Saldo de parcelas vencidas no recorte']]);
  note(section,'Previsões usam vencimentos; baixas usam o recebimento efetivo e vendas usam a data do pedido. Estes valores não representam saldo bancário, lucro ou margem.');
  if(productFilter)note(section,'O filtro de produto seleciona pedidos que contêm o item. Os totais financeiros continuam sendo do pedido inteiro, sem atribuí-los artificialmente a um único produto.');
  const full=h('details','eg-full-portfolio');full.append(h('summary','','Carteira completa no meu acesso'));metrics(full,[['Previsto · carteira completa',brl(state.expected_cents),'Parcelas dos pedidos ativos'],['Recebido · carteira completa',brl(state.received_cents),'Baixas registradas'],['A receber · carteira completa',brl(state.outstanding_cents),'Previsto menos baixas'],['Vencido · carteira completa',brl(state.overdue_cents),'Vencimento anterior a hoje']]);section.append(full);
  table(section,['Empresa','Parcela','Vencimento','Previsto','Recebido','Saldo','Situação',''],rows.map(row=>[row.company_name,row.number,day(row.date),brl(row.amount_cents),brl(row.paid_cents),brl(row.remaining_cents),row.overdue?'Vencido':row.remaining_cents?'A receber':'Recebido',row.remaining_cents>0?button('Registrar baixa',()=>receiptEditor(row)):h('span','eg-badge','Concluída')]));
  section.append(button('Exportar previsões / baixas CSV',()=>exportData('finance',['Empresa','Pedido','Parcela','Vencimento','Previsto (centavos)','Recebido (centavos)','Saldo (centavos)'],rows.map(row=>[row.company_name,row.order_id,row.number,row.date,row.amount_cents,row.paid_cents,row.remaining_cents]))));
  const items=new Map(data.products.filter(row=>!productFilter||row.id===productFilter).map(row=>[row.id,{name:row.name,sku:row.sku,quantity:0}]));
  for(const order of data.records.filter(row=>row.active!==false&&row.kind==='order'&&matchesRow(row)&&(!start||row.work_date>=start)&&(!end||row.work_date<=end)))for(const item of order.data.items||[]){if(productFilter&&item.product_id!==productFilter)continue;if(!items.has(item.product_id))items.set(item.product_id,{name:item.name,sku:item.sku,quantity:0});const current=items.get(item.product_id);current.quantity=M().sum([current.quantity,Number(item.quantity)]);}
  const ranked=[...items.values()].sort((a,b)=>b.quantity-a.quantity||a.name.localeCompare(b.name,'pt-BR')),ranking=card('Produtos mais e menos vendidos');note(ranking,'Unidades nos pedidos ativos pela data de fechamento. Produtos sem vendas permanecem com zero; a confirmação de entrega controla a baixa física separadamente.');
  table(ranking,['Mais vendidos · produto','Unidades'],ranked.slice(0,5).map(item=>[`${item.sku} · ${item.name}`,fmt(item.quantity)]));table(ranking,['Menos vendidos · produto (incluindo zero)','Unidades'],[...ranked].sort((a,b)=>a.quantity-b.quantity||a.name.localeCompare(b.name,'pt-BR')).slice(0,5).map(item=>[`${item.sku} · ${item.name}`,fmt(item.quantity)]));
  const history=card('Baixas efetivas no período');recordsList(history,periodRows.filter(row=>row.kind==='receipt'),row=>`${companyName(row.company_id)} · ${brl(row.data.amount_cents)}`);
 }

 function receiptEditor(installment){const order=data.records.find(row=>row.id===installment.order_id);openDialog('Registrar recebimento efetivo',form=>{note(form,`${installment.company_name} · parcela ${installment.number} · saldo ${brl(installment.remaining_cents)}. A baixa só deve ser registrada após o recebimento.`);const date=workDate(form),amount=field(form,'Valor recebido · R$','amount','text',real(installment.remaining_cents),true);date.min=order.work_date;amount.inputMode='decimal';const memo=notes(form);memo.maxLength=1000;return ()=>({date:date.value,installment_id:installment.id,amount_cents:M().money(amount.value),notes:memo.value.trim()});},payload=>command('receipt_add',payload,order));}
 function recordsList(section,rows,description,edit=null,extra=null){section.append(button('Exportar registros CSV',()=>exportData('records',['ID','Tipo','Data','Colaborador','Situação','Revisão','Dados informados'],rows.map(row=>[row.id,row.kind,row.work_date,person(row.subject_id),row.status,row.revision,JSON.stringify(row.data)]))));let page=0;const body=h('div','eg-records'),pager=h('div','eg-pager');section.append(body,pager);function paint(){body.replaceChildren();pager.replaceChildren();const sorted=[...rows].sort((a,b)=>b.work_date.localeCompare(a.work_date)||b.created_at?.localeCompare(a.created_at)||0);for(const row of sorted.slice(page*30,page*30+30)){const article=h('article','eg-record'),header=h('div','eg-record-head');header.append(h('h3','',`${day(row.work_date)} · ${labels[row.kind]||row.kind}`),h('span','eg-badge',labels[row.status]||row.status));article.append(header,h('p','',description(row)),h('p','muted',`Responsável: ${person(row.subject_id)} · Registrado por: ${person(row.created_by)} · revisão ${row.revision}`));if(row.data.notes)article.append(h('p','',row.data.notes));const actions=h('div','eg-actions');if(edit&&(context.can_manage||(row.subject_id===context.user_id&&row.created_by===context.user_id)))actions.append(button('Ajustar',()=>edit(row)));if(extra)actions.append(extra(row));if(context.can_delete){const remove=button('×',()=>voidEditor(row));remove.classList.add('eg-delete');remove.setAttribute('aria-label','Excluir/anular registro');remove.title='Excluir/anular registro';actions.append(remove);}article.append(actions);body.append(article);}if(!rows.length)body.append(h('p','eg-empty','Nenhum registro no período.'));const previous=button('Anterior',()=>{page--;paint();}),next=button('Próxima',()=>{page++;paint();});previous.disabled=page===0;next.disabled=(page+1)*30>=rows.length;pager.append(previous,h('span','',`${rows.length} registro(s) · página ${page+1}`),next);}paint();}
 function voidEditor(row){openDialog('Anular registro',form=>{note(form,'O registro sai dos indicadores ativos, mas seu histórico é preservado. O sistema verifica dependências e os saldos de estoque antes de reverter movimentos.');const reason=field(form,'Justificativa · 10 a 300 caracteres','reason','textarea','',true);reason.minLength=10;reason.maxLength=300;return ()=>reason.value.trim();},reason=>{if(reason.length<10)throw Error('Justifique a anulação em pelo menos 10 caracteres.');return command('void',{},row,reason);});}
 function auditView(){const section=card('Log mensal de auditoria');const form=h('form','eg-period'),month=field(form,'Mês da alteração · Manaus','month','month',context.today.slice(0,7),true),query=field(form,'Pesquisar ação, autor, registro ou justificativa','query','search'),submit=h('button','button secondary','Pesquisar');submit.type='submit';form.append(submit);section.append(form);const results=h('div','eg-audit-results');section.append(results);let current=[];const render=()=>{results.replaceChildren();const normalized=query.value.trim().toLocaleLowerCase('pt-BR'),rows=current.filter(row=>!normalized||JSON.stringify(row).toLocaleLowerCase('pt-BR').includes(normalized));note(results,`${rows.length} evento(s) no mês selecionado.`);table(results,['Data / hora Manaus','Autor','Ação','Entidade','Justificativa',''],rows.slice(0,100).map(row=>[new Intl.DateTimeFormat('pt-BR',{timeZone:'America/Manaus',dateStyle:'short',timeStyle:'short'}).format(new Date(row.occurred_at)),row.actor_name,row.action,row.entity,row.reason||'—',button('Detalhes',()=>openDialog('Detalhes auditados',body=>{body.append(h('pre','eg-json',JSON.stringify({antes:row.before_data,depois:row.after_data},null,2)));return ()=>null;}))]));if(rows.length>100)note(results,'A tela mostra os primeiros cem eventos. O CSV contém todos os resultados desta pesquisa.');results.append(button('Exportar log CSV',()=>exportData('audit',['Data UTC','Autor','ID do autor','Ação','Entidade','Registro','Motivo','Antes','Depois'],rows.map(row=>[row.occurred_at,row.actor_name,row.actor_id,row.action,row.entity,row.entity_id,row.reason,JSON.stringify(row.before_data),JSON.stringify(row.after_data)]))));};form.addEventListener('submit',async event=>{event.preventDefault();if(busy)return;lock(true);try{if(!/^\d{4}-\d{2}$/.test(month.value))throw Error('Escolha um mês válido.');const first=month.value+'-01',next=new Date(first+'T04:00:00Z');next.setUTCMonth(next.getUTCMonth()+1);current=await all('pdi_eg_audit',q=>q.gte('occurred_at',first+'T04:00:00Z').lt('occurred_at',next.toISOString()));if(valid())render();}catch(e){message(e.message,true);}finally{if(valid())lock(false);}});note(results,'Pesquise um mês para carregar os eventos. As exportações são registradas no servidor.');}
